using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class GatewayProjectChecks {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){
  var s=new SliceState();string empty=JsonUtility.ToJson(s);GatewayProjectText.Read(s,0);Check(empty==JsonUtility.ToJson(s)&&JsonUtility.FromJson<SliceState>(empty).Valid(),"Book/legacy save changed history");var p=new GatewayProject();Check(p.Begin(4,8,10)&&!p.Begin(4,8,10),"Duplicate project begun");
  var r=new TimberRelayMemory{count=4,cutter=2,carrier=1,source="tree",amount=3,time=10};Check(!p.Supply(r,false),"Historical relay credited");r.count=5;Check(!p.Supply(r,true)&&p.Supply(r,false)&&!p.Supply(r,false)&&p.supplied==3,"Paused/duplicate supplies credited");Check(!p.Placement(1,0,"player",8,11,false)&&!p.Placement(0,0,"player",7,11,false)&&p.Placement(0,0,"player",8,11,false)&&p.Placement(0,1,"creature",9,12,false),"Receipt boundary wrong");p.Retain(2);Check(!p.Shared&&!p.Use(0,13,true,false),"Detached player piece completed project");Check(p.Placement(0,0,"player",10,14,false)&&!p.Use(0,15,false,false)&&!p.Use(0,15,true,true)&&p.Use(0,15,true,false)&&!p.Use(0,15,true,false)&&p.completed==1&&p.Valid(),"Physical-use/duplicate completion guard failed");s.gatewayProject=p;s.Hybrid.time=15;Check(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(s)).Valid(),"Completed project save failed");p.creaturePieces|=p.playerPieces;Check(!p.Valid(),"Same piece assigned to two actors");Debug.Log("BWVR_GATEWAY_MODEL_PASS: fresh baselines, pause, bounded receipts, source separation, detached pieces, real-use requirement and one saved completion");
 }
 public static void VerifyRuntime(){
  Check(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var god=slice.GetComponentInChildren<CreatureHybrid>();var mind=god.GetComponent<CreatureCuriosity>();var world=slice.GetComponentInChildren<VillageResources>();var nav=world.Navigation;Check(!nav.TreeNavigationPending,"Wait for navigation");var site=god.GetComponent<CreatureConstructionLearning>().sites[0];var geometry=site.Capture();var recipe=site.Recipe;bool wasPaused=site.Paused;var field=typeof(QuestSlice).GetField("state",F);var original=(SliceState)field.GetValue(slice);var people=world.Gatherers;var positions=people.Select(a=>a.transform.position).ToArray();var rotations=people.Select(a=>a.transform.rotation).ToArray();var gp=god.transform.position;var gr=god.transform.rotation;var cooldowns=god.Targets.Where(t=>t.affordance!=null).ToDictionary(t=>t.affordance,t=>t.affordance.cooldown);var ideas=god.Targets.Where(t=>t.GetComponent<ConstructionInspiration>()!=null).ToArray();var ideaActive=ideas.Select(t=>t.gameObject.activeSelf).ToArray();SliceState test=null;
  void Place(ConstructionBlock b,Vector3 at){if(b.Shape==ConstructionShape.Beam){var rim=site.Local(at);rim.x=-1.25f;at=site.World(rim);}test.Hybrid.time+=1;Check((bool)typeof(QuestSlice).GetMethod("TryGrab",F).Invoke(slice,new object[]{1,b.Item}),"Native project grab rejected");Physics.SyncTransforms();typeof(QuestSlice).GetMethod("Release",F).Invoke(slice,new object[]{1,new Ray(at+Vector3.up*nav.Scale*12,Vector3.down)});Check(b.Attached,"Native project drop did not snap: "+b.Shape+" / snapped="+site.Snapped+" / wanted="+site.Local(at));for(int i=0;i<5;i++)site.Advance(.02f);}
  try{
   god.Interrupt("Gateway QA");site.Paused=false;site.ResetConstruction();site.Recipe=BuildRecipe.Arch;
   TimberRelayChecks.VerifyRuntime(s=>{Check(slice.ShowCreationBook(true),"Book did not open");slice.SelectCreationBook(CreationBookSection.Projects);var go=(GameObject)typeof(QuestSlice).GetField("outingGo",F).GetValue(slice);go.GetComponent<SpatialTarget>().Activate();Check(s.gatewayProject?.phase==GatewayPhase.Active&&!slice.BeginGatewayProject()&&s.gatewayProject.supplied==0&&site.Snapped==0&&s.playOuting?.phase!=PlayOutingPhase.Active,"Native Projects button reset world / started wrong outing");go.GetComponent<SpatialTarget>().Activate();Check(!slice.CreationBookOpen&&(Transform)typeof(QuestSlice).GetField("outingTarget",F).GetValue(slice)==site.transform,"Projects button did not mark yard");},s=>test=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(s)));
   Check(test?.gatewayProject?.supplied==3&&test.gatewayProject.phase==GatewayPhase.Active&&!test.gatewayProject.Shared,"Native cooperative stock did not advance project");field.SetValue(slice,test);test.developmentFocus=test.observeWithoutFoodWork=true;god.NewSeason();world.ResetWorld();slice.SetSanctuaryOpen(false);var palette=slice.GetComponentInChildren<GodToolPalette>();palette.Cancel();palette.Process(new Ray(Camera.main.transform.position,Camera.main.transform.forward),false,true,false,.1f,false);site.ResetConstruction();site.Recipe=BuildRecipe.Arch;
   foreach(var a in people){a.Cancel();a.GetComponent<VillagerExploration>().ResetTask();a.GetComponent<VillagerSocial>().ResetTask();a.GetComponent<VillagerBlockPlay>().ResetTask();slice.GetComponentInChildren<VillageFamilies>()?.Release(a.GetComponent<VillagerRoutine>());slice.GetComponentInChildren<VillageCathedral>()?.Cancel(a.GetComponent<VillagerRoutine>());a.transform.position=world.StoreApproach+Vector3.up*nav.Scale*600;}foreach(var idea in ideas)idea.gameObject.SetActive(false);
   var first=site.blocks.First(b=>b.Shape==ConstructionShape.Brick);var plan=ConstructionPatterns.Plan(BuildRecipe.Arch);bool seen=false;for(int i=0;i<24;i++){var wanted=site.World(Quaternion.Euler(0,i*15,0)*Vector3.forward*18);if(!god.GetComponent<IslandNavigator>().CanPlace(wanted,out var at))continue;god.transform.position=at;god.transform.LookAt(site.World(plan[0].position));god.GetComponent<IslandNavigator>().ResetRoute();Physics.SyncTransforms();if(god.CanSeeCue(first.GetComponent<HybridTarget>())){seen=true;break;}}Check(seen,"No shared-build viewing stage");Place(first,site.World(plan[0].position));Check(test.gatewayProject.playerPieces!=0&&test.gatewayProject.creaturePieces==0,"Player snap attribution missing");
   var next=site.blocks.First(b=>!b.Attached&&b.Shape==ConstructionShape.Brick&&b.CanBuild);foreach(var a in cooldowns.Keys)a.cooldown=a==next.GetComponent<CreatureAffordance>()?0:test.Hybrid.time+100000;int built=mind.built;for(int i=0;i<2000&&mind.built==built;i++){god.Tick(.05f);site.Advance(.02f);}Check(mind.built==built+1&&next.Attached&&next.creatureBuilt&&test.gatewayProject.Shared&&test.gatewayProject.phase==GatewayPhase.Active,"Native creature contribution failed");
   test.paused=true;string paused=JsonUtility.ToJson(test);Check(!slice.EndGatewayProject(),"Paused project ended");slice.Simulate(2);Check(paused==JsonUtility.ToJson(test),"Paused project changed");test.paused=false;site.Paused=false;site.ReturnLoose(first);site.RefreshGatewayEvidence(test);Check(test.gatewayProject.playerPieces==0&&test.gatewayProject.creaturePieces!=0,"Detached block retained project credit");Place(first,site.World(plan[0].position));
   typeof(QuestSlice).GetMethod("Save",F).Invoke(slice,null);typeof(QuestSlice).GetMethod("Load",F).Invoke(slice,null);test=(SliceState)field.GetValue(slice);god.NewSeason();world.ResetWorld();site.Recipe=BuildRecipe.Arch;site.Restore(test.construction);site.RefreshGatewayEvidence(test);test.developmentFocus=test.observeWithoutFoodWork=true;Check(test.Valid()&&test.gatewayProject.Shared&&test.gatewayProject.supplied==3&&site.Snapped==2,"Partial native save lost project/geometry");
   god.transform.position=world.StoreApproach+Vector3.up*nav.Scale*800;for(int turn=0;turn<10&&!site.RecipeComplete;turn++){ConstructionBlock piece=null;Vector3 point=default;foreach(var b in site.blocks.Where(b=>!b.Attached))if(site.TryRecipePlan(b,out point,out _)){piece=b;break;}Check(piece!=null,"No remaining arch placement");Place(piece,point);}Check(site.RecipeComplete&&test.gatewayProject.phase==GatewayPhase.Active,"Snapping alone completed project");
   var visitor=people[0].GetComponent<VillagerExploration>();Check(nav.Sample(site.World(new Vector3(0,0,-12)),nav.villager,12,out var start),"No gateway approach");visitor.transform.position=nav.ProjectFoot(start,nav.villager);visitor.GetComponent<IslandNavigator>().ResetRoute();visitor.GetComponent<VillagerSocial>().Memory.usedForms|=1<<(int)BuildRecipe.Arch;Check((bool)typeof(VillagerExploration).GetMethod("ChooseStructure",F).Invoke(visitor,null),"Existing structure chooser did not revisit the ready project");for(int i=0;i<3500&&test.gatewayProject.phase!=GatewayPhase.Complete;i++){test.Hybrid.time+=.05f;visitor.Tick(.05f,false);site.Advance(.02f);}Check(test.gatewayProject.phase==GatewayPhase.Complete&&test.gatewayProject.completed==1&&test.gatewayProject.visitor==0&&visitor.GetComponent<VillagerSocial>().Memory.constructionUses>0,"Native walkthrough did not complete project");int count=test.gatewayProject.completed;Check(!slice.BeginGatewayProject()&&site.RecipeComplete&&test.gatewayProject.completed==count,"Replay destroyed finished arch");
   typeof(QuestSlice).GetMethod("Save",F).Invoke(slice,null);typeof(QuestSlice).GetMethod("Load",F).Invoke(slice,null);test=(SliceState)field.GetValue(slice);god.NewSeason();Check(test.Valid()&&test.gatewayProject.phase==GatewayPhase.Complete&&test.gatewayProject.completed==1&&test.gatewayProject.Shared,"Completed project save failed");Debug.Log("BWVR_GATEWAY_RUNTIME_PASS: native Book begin/mark, real cooperative timber receipt, native player pickup/snap, utility-selected creature placement, pause/detach, partial native Save/Load with geometry, real finished arch and villager walkthrough, one completion and non-destructive replay guard");
  }finally{god.Interrupt("Gateway QA complete");foreach(var a in people){a.Cancel();a.GetComponent<VillagerExploration>().ResetTask();}site.Recipe=recipe;site.Restore(geometry);site.Paused=wasPaused;field.SetValue(slice,original);god.NewSeason();world.ResetWorld();foreach(var p in cooldowns)p.Key.cooldown=p.Value;for(int i=0;i<ideas.Length;i++)ideas[i].gameObject.SetActive(ideaActive[i]);god.transform.SetPositionAndRotation(gp,gr);god.GetComponent<IslandNavigator>().ResetRoute();for(int i=0;i<people.Length;i++){people[i].transform.SetPositionAndRotation(positions[i],rotations[i]);people[i].GetComponent<IslandNavigator>().ResetRoute();}slice.SetSanctuaryOpen(false);Physics.SyncTransforms();}
 }
}
}
